    for (size_t i = 0; i < sizeof(s_table)/sizeof(s_table[0]); ++i) {
        uint32_t pc = s_table[i].pc & 0x0fffffff;
        if (pc >= 0x0c000000) {
            uint32_t idx = (pc - 0x0c000000) >> 1;
            if (idx < 2097152) g_ram_blocks[idx] = s_table[i].fn;
        } else {
            uint32_t idx = pc >> 1;
            if (idx < 2097152) g_rom_blocks[idx] = s_table[i].fn;
        }
    }
